"""Compile a two-class growth change over the immutable seven-class weak runtime."""
import argparse
import importlib.util
import json
import os
from pathlib import Path
import shutil

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
OLD = PHASE.parent / 'admission-followup'
PACKAGE = Path('org/eclipse/rdf4j/sail/lmdb/evaluation')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if not args.slot_granted:
        raise ValueError('Exclusive Java slot required')
    spec = importlib.util.spec_from_file_location('growth_contract_runner', HERE / 'run_contracts.py')
    helper = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(helper)
    red = json.loads((HERE / 'validation/red-all-v1/receipt.json').read_text())
    if not red['passed'] or red['results'] != dict(tests=12, failures=7, errors=0, skipped=0):
        raise ValueError('The accepted pre-implementation red evidence is required')
    seal = json.loads((HERE / 'contract-seal-v1.json').read_text())
    contract = HERE / 'test-src' / PACKAGE / 'NativeDirectValueMemoGrowthContractTest.java'
    if helper.digest(contract) != seal['sha256']:
        raise ValueError('The sealed growth contract changed')
    small = json.loads((HERE / 'validation/red-small-v1/receipt.json').read_text())
    if not small['passed'] or small['results'] != dict(tests=1, failures=1, errors=0, skipped=0):
        raise ValueError('Smallest in-repository failure must precede the growth change')
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    shutil.copyfile(__file__, output / 'compiler-at-launch.py')
    baseline = OLD / 'runtime-v2'
    cp = (baseline / 'classpath.txt').read_text().strip()
    prefix = output / 'classes'
    shutil.copytree(baseline / 'classes', prefix)
    source = PHASE / 'implementation-src' / PACKAGE / 'NativeDirectValueMemo.java'
    copied = output / 'src' / PACKAGE / source.name
    copied.parent.mkdir(parents=True)
    shutil.copyfile(source, copied)
    emitted = output / 'emitted-classes'
    emitted.mkdir()
    result = helper.run(output, 'compile', [helper.JAVA_HOME / 'bin/javac', '--release', '25', '-g',
        '-proc:none', '-implicit:none', '-sourcepath', '', '-encoding', 'UTF-8', '-cp', cp,
        '-d', emitted, copied])
    if result['exitCode']:
        print((output / 'compile.log').read_text())
        raise RuntimeError('Growth prefix did not compile')
    expected = {str(PACKAGE / (name + '.class')) for name in ('NativeDirectValueMemo', 'NativeDirectValueMemo$WeakValueEntry')}
    if set(helper.tree(emitted)) != expected:
        raise ValueError('Unexpected emitted classes')
    for name in sorted(expected):
        shutil.copyfile(emitted / name, prefix / name)
    old_classes, new_classes = helper.tree(baseline / 'classes'), helper.tree(prefix)
    changed = sorted(name for name in old_classes if old_classes[name] != new_classes[name])
    if set(old_classes) != set(new_classes) or not set(changed) <= expected:
        raise ValueError('Non-memo bytecode changed')
    for name in ('NativeResultMaterializer.java', 'NativeProjectedBindingSet.java'):
        if helper.digest(OLD / 'implementation-src' / PACKAGE / name) != helper.digest(PHASE / 'implementation-src' / PACKAGE / name):
            raise ValueError('Ownership integration source changed')
    (output / 'classpath.txt').write_text(os.pathsep.join([str(prefix), *cp.split(os.pathsep)[1:]]) + '\n')
    helper.write(output / 'class-files.json', new_classes)
    helper.write(output / 'compile-receipt.json', {
        'compiled': True, 'qualifiedForTiming': False, 'changedClassFiles': changed,
        'unchangedCompanionClassFiles': sorted(set(new_classes) - set(changed)),
        'ownershipIntegrationSourcesIdentical': True, 'sourceSha256': helper.digest(source),
        'source': str(source), 'classpathFile': str(output / 'classpath.txt'),
        'classpathSha256': helper.digest(output / 'classpath.txt'),
        'classFilesSha256': helper.digest(output / 'class-files.json')})
    print(json.dumps({'output': str(output), 'prefixClasses': len(new_classes), 'changedClasses': changed}))


if __name__ == '__main__':
    main()
